import{_ as t,o as r,c as i,a2 as n}from"./chunks/framework.vLhlLNVn.js";const b=JSON.parse('{"title":"Farben und Visualisierung","description":"","frontmatter":{"order":3,"adapter":"wled","editLink":"https://github.com/DrozmotiX/ioBroker.wled/edit/main/docs/de/04.fehlerbehebung/03.farben-und-vis.md"},"headers":[],"relativePath":"de/adapter/wled/fehlerbehebung/farben-und-vis.md","filePath":"de/adapter/wled/fehlerbehebung/farben-und-vis.md","lastUpdated":null}'),a={name:"de/adapter/wled/fehlerbehebung/farben-und-vis.md"};function d(s,e,o,l,h,c){return r(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="farben-und-visualisierung" tabindex="-1">Farben und Visualisierung <a class="header-anchor" href="#farben-und-visualisierung" aria-label="Permalink to &quot;Farben und Visualisierung&quot;">​</a></h1><p><a id="colour-jump-back-forth-transition"></a></p><h2 id="warum-springt-die-farbe-hin-und-her-oder-die-transition-zeit-steht-wieder-auf-7" tabindex="-1">Warum springt die Farbe hin und her, oder die Transition-Zeit steht wieder auf 7? <a class="header-anchor" href="#warum-springt-die-farbe-hin-und-her-oder-die-transition-zeit-steht-wieder-auf-7" aria-label="Permalink to &quot;Warum springt die Farbe hin und her, oder die Transition-Zeit steht wieder auf 7?&quot;">​</a></h2><p><strong>Kurz:</strong> <code>transition</code> ist die Überblendzeit von WLED in Zehntelsekunden. <code>7</code> ist der Standard von WLED (rund 0,7 Sekunden). Setzt du den Wert über den Adapter, gilt er nur bis zum nächsten Neustart von WLED. Dauerhaft änderst du ihn in WLED unter „LED Preferences“, „Default transition time“. Springt die Farbe hin und her, setz <code>transition</code> auf <code>0</code> oder schick schnelle Farbwechsel mit <code>tt: 0</code>.</p><h3 id="warum-die-transition-zeit-wieder-auf-7-steht" tabindex="-1">Warum die Transition-Zeit wieder auf 7 steht <a class="header-anchor" href="#warum-die-transition-zeit-wieder-auf-7-steht" aria-label="Permalink to &quot;Warum die Transition-Zeit wieder auf 7 steht&quot;">​</a></h3><p>WLED speichert die Überblendzeit an zwei Stellen: den aktuellen Wert und den Standardwert aus den Einstellungen. Der Adapter schreibt über <code>wled.0.&lt;Gerät&gt;.transition</code> nur den aktuellen Wert. Beim Neustart von WLED, etwa nach einem Stromausfall oder Update, lädt WLED wieder den Standardwert, ab Werk 750 ms. Den meldet WLED als <code>7</code>.</p><p>Auch ein Preset kann den Wert zurücksetzen: Speichert WLED ein Preset, steht die Überblendzeit mit darin, und beim Laden gilt sie wieder.</p><p>So stellst du die Zeit dauerhaft ein:</p><ol><li>Öffne die Weboberfläche des Geräts unter <code>http://192.168.x.y</code>.</li><li>Geh zu „Config“, „LED Preferences“ und such den Bereich „Transitions“.</li><li>Trag bei „Default transition time“ die Zeit in Millisekunden ein, zum Beispiel <code>0</code> für sofortige Wechsel, und speichere.</li><li>Speichere Presets, die eine andere Zeit enthalten, mit der neuen Zeit erneut.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>In der Weboberfläche gibst du Millisekunden ein, im Datenpunkt <code>transition</code> stehen Zehntelsekunden. <code>1500</code> ms in WLED erscheinen im Adapter als <code>15</code>.</p></div><h3 id="warum-die-farbe-hin-und-her-springt" tabindex="-1">Warum die Farbe hin und her springt <a class="header-anchor" href="#warum-die-farbe-hin-und-her-springt" aria-label="Permalink to &quot;Warum die Farbe hin und her springt&quot;">​</a></h3><p>Jeder Farbwechsel ist ein eigener Befehl. Ziehst du in VIS am Farbwähler, schickt das Widget viele Werte hintereinander. WLED blendet jeden Wechsel über die eingestellte Zeit über und meldet seinen Zustand zurück, über WebSocket höchstens etwa einmal pro Sekunde. Kommt eine Rückmeldung zwischen zwei deiner Befehle an, schreibt der Adapter den älteren Wert in den Datenpunkt, und der Farbwähler springt kurz zurück.</p><p>Das hilft:</p><ul><li>Setz <code>wled.0.&lt;Gerät&gt;.transition</code> auf <code>0</code> oder stell die Zeit in WLED dauerhaft auf <code>0</code> (siehe oben). Dann gibt es keine Überblendung, die sich mit dem nächsten Befehl überschneidet.</li><li>Brauchst du die Überblendung sonst, schick Farbwechsel aus Skripten über <code>action</code> mit <code>&quot;tt&quot;:0</code>, zum Beispiel <code>{&quot;seg&quot;:[{&quot;id&quot;:0,&quot;col&quot;:[[255,0,0]]}],&quot;tt&quot;:0}</code>. Das gilt nur für diesen Befehl.</li></ul><p><strong>Ab v0.10.0:</strong> Schnelle Schreibzugriffe auf dasselbe Gerät fasst der Adapter innerhalb der „Wartezeit zum Bündeln“ (Standard 50 ms) zu einem Befehl zusammen. Beim Ziehen am Farbwähler kommen dadurch weniger Befehle bei WLED an (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/926" target="_blank" rel="noreferrer">#926</a>).</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/farbe#dim-up-down-slowly-connect">Langsam dimmen mit tt und transition</a> · <a href="#colour-picker-vis-switch-wled">Farbwähler schaltet WLED aus</a></p><p><a id="hex-colour-not-work-work"></a></p><h2 id="warum-funktioniert-die-hex-farbe-nicht-oder-falsch-weißkanal-nach-wled-update" tabindex="-1">Warum funktioniert die HEX-Farbe nicht oder falsch (Weißkanal, nach WLED-Update)? <a class="header-anchor" href="#warum-funktioniert-die-hex-farbe-nicht-oder-falsch-weißkanal-nach-wled-update" aria-label="Permalink to &quot;Warum funktioniert die HEX-Farbe nicht oder falsch (Weißkanal, nach WLED-Update)?&quot;">​</a></h2><p><strong>Kurz:</strong> Bis v0.9.2 hat das Schreiben von HEX-Farben zwei bekannte Fehler: Bei RGBW-Streifen springt der Weißkanal auf voll, und die dritte Farbe <code>col.2_HEX</code> wirkt nicht. Beide sind ab v0.9.3 behoben. Bis dahin nimmst du die RGB-Datenpunkte <code>seg.&lt;Segment&gt;.col.0</code> bis <code>col.2</code> oder einen HEX-Wert mit allen 8 Stellen.</p><h3 id="bekannte-fehler-und-ab-wann-sie-behoben-sind" tabindex="-1">Bekannte Fehler und ab wann sie behoben sind <a class="header-anchor" href="#bekannte-fehler-und-ab-wann-sie-behoben-sind" aria-label="Permalink to &quot;Bekannte Fehler und ab wann sie behoben sind&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Was passiert</th><th>Betroffen</th><th>Behoben</th></tr></thead><tbody><tr><td>HEX-Wert wird falsch in RGB umgerechnet, Farbwechsel per HEX wirkt nicht</td><td>bis v0.2.5</td><td>v0.2.6</td></tr><tr><td>HEX-Wert hat keinen Weißkanal, bei RGBW gehen Werte verloren</td><td>bis v0.6.7</td><td>v0.7.1</td></tr><tr><td>Ein HEX-Wert mit 6 Stellen setzt bei RGBW den Weißkanal auf 255</td><td>bis v0.9.2</td><td>v0.9.3 (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/907" target="_blank" rel="noreferrer">#907</a>)</td></tr><tr><td><code>col.2_HEX</code> wirkt nicht, die dritte Farbe bekommt den Wert von <code>col.1_HEX</code></td><td>bis v0.9.2</td><td>v0.9.3 (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/906" target="_blank" rel="noreferrer">#906</a>)</td></tr></tbody></table><p>Die Ursache bis v0.9.2: Ein HEX-Wert mit 6 Stellen hat keinen Weißanteil. Der Adapter wertet das als „voll“ und schickt <code>255</code> als vierten Wert mit. Außerdem liest er für die dritte Farbe versehentlich <code>col.1_HEX</code>.</p><p><strong>Ab v0.9.3:</strong> Ein HEX-Wert mit 6 Stellen lässt den Weißkanal so, wie er am Gerät gerade ist. Ein HEX-Wert mit 8 Stellen (<code>#rrggbbww</code>) setzt ihn mit. <code>col.2_HEX</code> setzt die dritte Farbe (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/906" target="_blank" rel="noreferrer">#906</a>, <a href="https://github.com/DrozmotiX/ioBroker.wled/issues/907" target="_blank" rel="noreferrer">#907</a>).</p><h3 id="so-umgehst-du-die-fehler-bis-v0-9-2" tabindex="-1">So umgehst du die Fehler bis v0.9.2 <a class="header-anchor" href="#so-umgehst-du-die-fehler-bis-v0-9-2" aria-label="Permalink to &quot;So umgehst du die Fehler bis v0.9.2&quot;">​</a></h3><ul><li><strong>RGBW-Streifen:</strong> Schreib in <code>seg.&lt;Segment&gt;.col.0</code> den Text <code>[r,g,b,w]</code>, zum Beispiel <code>[255,120,0,0]</code>. Damit bestimmst du den Weißkanal selbst.</li><li><strong>Oder HEX mit 8 Stellen:</strong> <code>#ff780000</code> setzt Orange ohne Weiß.</li><li><strong>Dritte Farbe:</strong> Schreib sie über <code>seg.&lt;Segment&gt;.col.2</code> als <code>[r,g,b]</code>.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Ein reiner RGB-Streifen hat keinen Weißkanal. Dort fällt der Fehler mit dem Weißkanal nicht auf.</p></div><h3 id="hex-werte-aktualisieren-sich-nach-einem-wled-update-nicht" tabindex="-1">HEX-Werte aktualisieren sich nach einem WLED-Update nicht <a class="header-anchor" href="#hex-werte-aktualisieren-sich-nach-einem-wled-update-nicht" aria-label="Permalink to &quot;HEX-Werte aktualisieren sich nach einem WLED-Update nicht&quot;">​</a></h3><p>Nach einem Update der Firmware auf WLED 0.14.2 haben Nutzer gemeldet, dass die HEX-Datenpunkte die Farbe am Gerät nicht mehr nachführten. Geholfen hat, das Gerät im Adapter zu löschen und neu hinzuzufügen. Eine Ursache im Adapter ist nicht bekannt.</p><ol><li>Prüf zuerst, ob <code>seg.&lt;Segment&gt;.col.0</code> (RGB) sich ändert, wenn du in der WLED-Oberfläche die Farbe wechselst. Ändert sich auch der RGB-Wert nicht, kommen gar keine Rückmeldungen an, siehe <a href="./../hintergrund/verbindung-und-aktualisierung#states-only-updated-after-30">Warum werden Zustände erst nach 30 Sekunden aktualisiert?</a>.</li><li>Ändert sich nur der HEX-Wert nicht, lösch das Gerät und füg es neu hinzu, wie unter <a href="./../anleitungen/geraete-verwalten#remove-wled-device-adapter">Wie entferne ich ein WLED-Gerät aus dem Adapter?</a> beschrieben.</li></ol><p><strong>Siehe auch:</strong> <a href="./../anleitungen/farbe#control-white-channel-rgbw-sk6812">Weißkanal steuern</a> · <a href="./../anleitungen/vis-und-smarthome#state-use-colour-picker-vis">Farbwähler in VIS</a> · <a href="#colour-picker-vis-switch-wled">Farbwähler schaltet WLED aus</a></p><p><a id="colour-picker-vis-switch-wled"></a></p><h2 id="warum-schaltet-der-farbwahler-in-vis-wled-aus" tabindex="-1">Warum schaltet der Farbwähler in VIS WLED aus? <a class="header-anchor" href="#warum-schaltet-der-farbwahler-in-vis-wled-aus" aria-label="Permalink to &quot;Warum schaltet der Farbwähler in VIS WLED aus?&quot;">​</a></h2><p><strong>Kurz:</strong> Der Adapter schaltet WLED bei einem Farbwechsel nicht aus, er schickt nur die Farben. Wird der Streifen dunkel, kommt fast immer Schwarz oder eine sehr dunkle Farbe an. Häufigste Ursache: Der Farbwähler ist an den RGB-Datenpunkt <code>seg.0.col.0</code> gebunden statt an <code>seg.0.col.0_HEX</code>. Bind ihn an den HEX-Datenpunkt und regle die Helligkeit getrennt über <code>bri</code>.</p><h3 id="pruf-zuerst-ob-wled-wirklich-aus-ist" tabindex="-1">Prüf zuerst, ob WLED wirklich aus ist <a class="header-anchor" href="#pruf-zuerst-ob-wled-wirklich-aus-ist" aria-label="Permalink to &quot;Prüf zuerst, ob WLED wirklich aus ist&quot;">​</a></h3><p>Schau nach dem Farbwechsel auf <code>wled.0.&lt;Gerät&gt;.on</code>. Steht er noch auf <code>true</code>, ist WLED an und zeigt nur eine schwarze Farbe. Schau dann auf <code>seg.0.col.0</code>: Steht dort <code>[0,0,0]</code> oder <code>[0,0,0,0]</code>, hat der Farbwähler Schwarz geschickt.</p><h3 id="farbwert-weißkanal-und-helligkeit" tabindex="-1">Farbwert, Weißkanal und Helligkeit <a class="header-anchor" href="#farbwert-weißkanal-und-helligkeit" aria-label="Permalink to &quot;Farbwert, Weißkanal und Helligkeit&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Was</th><th>Datenpunkt</th><th>Wirkung</th></tr></thead><tbody><tr><td>Farbton</td><td><code>seg.&lt;Segment&gt;.col.0_HEX</code></td><td>Rot, Grün, Blau als <code>#rrggbb</code></td></tr><tr><td>Weißkanal (nur RGBW)</td><td>vierter Wert in <code>col.0</code> oder letzte zwei Stellen von <code>col.0_HEX</code></td><td>zusätzliches Weiß</td></tr><tr><td>Helligkeit</td><td><code>bri</code> und <code>seg.&lt;Segment&gt;.bri</code></td><td>wie hell das Ganze leuchtet</td></tr><tr><td>Ein/Aus</td><td><code>on</code></td><td>schaltet das Licht</td></tr></tbody></table><p>Manche Farbräder mit eigenem Helligkeitsregler rechnen die Helligkeit in die Farbe ein. Ziehst du dort die Helligkeit auf null, schicken sie <code>#000000</code>, also Schwarz. WLED bleibt dann an, aber dunkel. Nimm darum für die Helligkeit einen eigenen Schieberegler auf <code>bri</code> und lass den Farbwähler nur den Farbton schicken.</p><h3 id="warum-der-rgb-datenpunkt-schwarz-ergibt" tabindex="-1">Warum der RGB-Datenpunkt Schwarz ergibt <a class="header-anchor" href="#warum-der-rgb-datenpunkt-schwarz-ergibt" aria-label="Permalink to &quot;Warum der RGB-Datenpunkt Schwarz ergibt&quot;">​</a></h3><p><code>seg.0.col.0</code> erwartet Text wie <code>[255,0,0]</code>. Ein Farbwähler schreibt aber <code>#ff0000</code> oder <code>rgb(255,0,0)</code>. Diesen Text kann der Adapter nicht in Zahlen zerlegen. Er schickt dann einen ungültigen Wert, den WLED als Schwarz übernimmt.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Bind Farbwähler immer an <code>seg.&lt;Segment&gt;.col.0_HEX</code>. Den RGB-Datenpunkt <code>col.0</code> nimmst du nur in Skripten, die den Text <code>[r,g,b]</code> selbst bauen.</p></div><p><strong>Bis v0.9.2:</strong> Bei RGBW-Streifen setzt jeder HEX-Wert aus dem Farbwähler den Weißkanal auf voll. Das Licht wird dann nicht dunkel, sondern blass weißlich. Abhilfe steht unter <a href="#hex-colour-not-work-work">Warum funktioniert die HEX-Farbe nicht oder falsch?</a>.</p><h3 id="ein-alias-fur-das-farbrad" tabindex="-1">Ein Alias für das Farbrad <a class="header-anchor" href="#ein-alias-fur-das-farbrad" aria-label="Permalink to &quot;Ein Alias für das Farbrad&quot;">​</a></h3><p>Willst du ein Farbrad, das Ein/Aus, Helligkeit und Farbe zusammen bedient, oder eine Lampe für Alexa oder Google Home, leg ein Alias-Gerät an:</p><table tabindex="0"><thead><tr><th>Datenpunkt im Alias</th><th>Rolle</th><th>Ziel</th></tr></thead><tbody><tr><td><code>on</code></td><td><code>switch.light</code></td><td><code>wled.0.&lt;Gerät&gt;.on</code></td></tr><tr><td><code>helligkeit</code></td><td><code>level.dimmer</code> (0 bis 100 %)</td><td><code>wled.0.&lt;Gerät&gt;.bri</code>, mit Umrechnung</td></tr><tr><td><code>farbe</code></td><td><code>level.color.rgb</code></td><td><code>wled.0.&lt;Gerät&gt;.seg.0.col.0_HEX</code></td></tr></tbody></table><p>Wie du das Alias Schritt für Schritt anlegst, steht unter <a href="./../anleitungen/vis-und-smarthome#connect-wled-iot-adapter-switch">Wie binde ich WLED in den iot-Adapter ein?</a>.</p><p><strong>Ab v0.10.0:</strong> Der Adapter legt diese Struktur selbst an: <code>wled.0.&lt;Gerät&gt;.light.on</code>, <code>light.dimmer</code> (0 bis 100 %) und <code>light.rgb</code> (HEX) für das Hauptsegment. Ein Farbrad bindest du direkt an <code>light.rgb</code> (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/328" target="_blank" rel="noreferrer">#328</a>).</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/vis-und-smarthome#state-use-colour-picker-vis">Farbwähler in VIS</a> · <a href="#colour-jump-back-forth-transition">Farbe springt hin und her</a></p><p><a id="vis-2-editor-freeze-pick"></a></p><h2 id="warum-friert-der-vis-2-editor-ein-wenn-ich-seg-0-fx-im-dropdown-wahle" tabindex="-1">Warum friert der VIS-2-Editor ein, wenn ich seg.0.fx im Dropdown wähle? <a class="header-anchor" href="#warum-friert-der-vis-2-editor-ein-wenn-ich-seg-0-fx-im-dropdown-wahle" aria-label="Permalink to &quot;Warum friert der VIS-2-Editor ein, wenn ich seg.0.fx im Dropdown wähle?&quot;">​</a></h2><p><strong>Kurz:</strong> Das liegt am Widget, nicht am Adapter. <code>seg.0.fx</code> bringt die Namen aller Effekte als Werteliste mit, bei WLED 0.15 sind das 187. Ein Widget aus der „vis-2-widgets-collection“ hat dafür im Editor je Effekt eine eigene Zeile angelegt, und das bremst den Editor bis zum Stillstand. Ab Version 2.3.3 der Widget-Sammlung gibt es dafür die Einstellung <code>ignoreCommonStates</code>.</p><h3 id="warum-das-passiert" tabindex="-1">Warum das passiert <a class="header-anchor" href="#warum-das-passiert" aria-label="Permalink to &quot;Warum das passiert&quot;">​</a></h3><p>Der Adapter hängt an <code>seg.&lt;Segment&gt;.fx</code> und <code>seg.&lt;Segment&gt;.pal</code> die Liste der Effekte und Paletten, die das Gerät meldet. So zeigen Admin und VIS die Namen statt der Nummern an. Manche Widgets lesen diese Liste beim Verbinden und bauen daraus ihre Einstellungen. Bei fast 200 Einträgen wird das im Editor zu viel.</p><h3 id="so-lost-du-es" tabindex="-1">So löst du es <a class="header-anchor" href="#so-lost-du-es" aria-label="Permalink to &quot;So löst du es&quot;">​</a></h3><ol><li>Aktualisiere den Adapter „vis-2-widgets-collection“ auf mindestens Version 2.3.3.</li><li>Markier im VIS-2-Editor das Widget und setz die Einstellung <code>ignoreCommonStates</code>. Was sie genau tut, zeigt der Hinweis (i) neben der Einstellung.</li><li>Wähl erst danach <code>seg.0.fx</code> als Datenpunkt aus.</li></ol><h3 id="mit-alteren-versionen-der-widget-sammlung" tabindex="-1">Mit älteren Versionen der Widget-Sammlung <a class="header-anchor" href="#mit-alteren-versionen-der-widget-sammlung" aria-label="Permalink to &quot;Mit älteren Versionen der Widget-Sammlung&quot;">​</a></h3><p>Kannst du nicht aktualisieren, nimm für den Effekt ein anderes Widget, das keine Werteliste auswertet, zum Beispiel ein Zahlenfeld, und schreib die Effektnummer direkt. Die Nummern findest du unter <a href="./../anleitungen/effekte-und-presets#numbers-names-effects-palettes-scripts">Wo finde ich die Nummern und Namen von Effekten und Paletten für Skripte?</a>.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Ist der Editor schon eingefroren, schließ den Browser-Tab und öffne den Editor neu. Wähl das Widget dann nicht mehr mit <code>seg.0.fx</code> aus, bevor du die Einstellung oben gesetzt oder das Widget getauscht hast.</p></div><p><strong>Siehe auch:</strong> <a href="./../anleitungen/vis-und-smarthome#choose-effect-palette-vis-as">Wie wähle ich Effekt und Palette in VIS als Dropdown?</a> · <a href="./../anleitungen/vis-und-smarthome#ready-made-vis-view-wled">Gibt es eine fertige VIS-Ansicht?</a></p>',59)])])}const m=t(a,[["render",d]]);export{b as __pageData,m as default};
